def main() -> None:
    path = Path("data/formatting_pairs_v1.jsonl")
    assert path.exists()
    existing = set()
    with path.open() as f:
        for line in f:
            existing.add(json.loads(line)["prompt"])
    new = [r for r in ROWS if r["prompt"] not in existing]
    with path.open("a") as f:
        for row in new:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
    counts = Counter()
    reg = Counter()
    topic = Counter()
    with path.open() as f:
        all_rows = [json.loads(line) for line in f]
    for r in all_rows:
        counts[r["context"]] += 1
        if "register" in r:
            reg[r["register"]] += 1
        if "topic_area" in r:
            topic[r["topic_area"]] += 1
    print(f"Appended: {len(new)} new (skipped {len(ROWS)-len(new)} dupes)")
    print(f"Total: {len(all_rows)}\n")
    print("By context:")
    for c, n in sorted(counts.items()):
        print(f"  {c:18} {n}")
    print("\nBy register:")
    for r, n in sorted(reg.items()):
        print(f"  {r:20} {n}")
    print("\nBy topic_area (new):")
    for t, n in sorted(topic.items()):
        print(f"  {t:15} {n}")


if __name__ == "__main__":
    main()
